87	/// Context is a wrapper for the SQLite function
88	/// evaluation context.
89	pub struct Context<'a> {
90	    ctx: *mut sqlite3_context,
91	    args: &'a [*mut sqlite3_value],
92	}
93	
94	impl Context<'_> {
95	    /// Returns the number of arguments to the function.
96	    #[inline]
97	    #[must_use]
98	    pub fn len(&self) -> usize {
99	        self.args.len()
100	    }
101	
102	    /// Returns `true` when there is no argument.
103	    #[inline]
104	    #[must_use]
105	    pub fn is_empty(&self) -> bool {
106	        self.args.is_empty()
107	    }
108	
109	    /// Returns the `idx`th argument as a `T`.
110	    ///
111	    /// # Failure
112	    ///
113	    /// Will panic if `idx` is greater than or equal to
114	    /// [`self.len()`](Context::len).
115	    ///
116	    /// Will return Err if the underlying SQLite type cannot be converted to a
117	    /// `T`.
118	    pub fn get<T: FromSql>(&self, idx: usize) -> Result<T> {
119	        let arg = self.args[idx];
120	        let value = unsafe { ValueRef::from_value(arg) };
121	        FromSql::column_result(value).map_err(|err| match err {
122	            FromSqlError::InvalidType => {
123	                Error::InvalidFunctionParameterType(idx, value.data_type())
124	            }
125	            FromSqlError::OutOfRange(i) => Error::IntegralValueOutOfRange(idx, i),
126	            FromSqlError::Utf8Error(err) => Error::Utf8Error(idx, err),
127	            FromSqlError::Other(err) => {
128	                Error::FromSqlConversionFailure(idx, value.data_type(), err)
129	            }
130	            FromSqlError::InvalidBlobSize { .. } => {
131	                Error::FromSqlConversionFailure(idx, value.data_type(), Box::new(err))
132	            }
133	        })
134	    }
135	
136	    /// Return raw pointer at `idx`
137	    /// # Safety
138	    /// This function is unsafe because it uses raw pointer and cast
139	    #[cfg(feature = "pointer")]
140	    #[must_use]
141	    pub unsafe fn get_pointer<T: 'static>(
142	        &self,
143	        idx: usize,
144	        ptr_type: &'static std::ffi::CStr,
145	    ) -> Option<&T> {
146	        let arg = self.args[idx];
147	        debug_assert_eq!(unsafe { ffi::sqlite3_value_type(arg) }, ffi::SQLITE_NULL);
148	        unsafe {
149	            ffi::sqlite3_value_pointer(arg, ptr_type.as_ptr())
150	                .cast::<T>()
151	                .as_ref()
152	        }
153	    }
154	
155	    /// Returns the `idx`th argument as a `ValueRef`.
156	    ///
157	    /// # Failure
158	    ///
159	    /// Will panic if `idx` is greater than or equal to
160	    /// [`self.len()`](Context::len).
161	    #[inline]
162	    #[must_use]
163	    pub fn get_raw(&self, idx: usize) -> ValueRef<'_> {
164	        let arg = self.args[idx];
165	        unsafe { ValueRef::from_value(arg) }
166	    }
167	
168	    /// Returns the `idx`th argument as a `SqlFnArg`.
169	    /// To be used when the SQL function result is one of its arguments.
170	    #[inline]
171	    #[must_use]
172	    pub fn get_arg(&self, idx: usize) -> SqlFnArg {
173	        assert!(idx < self.len());
174	        SqlFnArg { idx }
175	    }
176	
177	    /// Returns the subtype of `idx`th argument.
178	    ///
179	    /// # Failure
180	    ///
181	    /// Will panic if `idx` is greater than or equal to
182	    /// [`self.len()`](Context::len).
183	    #[must_use]
184	    pub fn get_subtype(&self, idx: usize) -> c_uint {
185	        let arg = self.args[idx];
186	        unsafe { ffi::sqlite3_value_subtype(arg) }
187	    }
188	
189	    /// Fetch or insert the auxiliary data associated with a particular
190	    /// parameter. This is intended to be an easier-to-use way of fetching it
191	    /// compared to calling [`get_aux`](Context::get_aux) and
192	    /// [`set_aux`](Context::set_aux) separately.
193	    ///
194	    /// See `https://www.sqlite.org/c3ref/get_auxdata.html` for a discussion of
195	    /// this feature, or the unit tests of this module for an example.
196	    ///
197	    /// # Failure
198	    ///
199	    /// Will panic if `arg` is greater than or equal to
200	    /// [`self.len()`](Context::len).
201	    pub fn get_or_create_aux<T, E, F>(&self, arg: c_int, func: F) -> Result<Arc<T>>
202	    where
203	        T: Send + Sync + 'static,
204	        E: Into<Box<dyn std::error::Error + Send + Sync + 'static>>,
205	        F: FnOnce(ValueRef<'_>) -> Result<T, E>,
206	    {
207	        if let Some(v) = self.get_aux(arg)? {
208	            Ok(v)
209	        } else {
210	            let vr = self.get_raw(arg as usize);
211	            self.set_aux(
212	                arg,
213	                func(vr).map_err(|e| Error::UserFunctionError(e.into()))?,
214	            )
215	        }
216	    }
217	
218	    /// Sets the auxiliary data associated with a particular parameter. See
219	    /// `https://www.sqlite.org/c3ref/get_auxdata.html` for a discussion of
220	    /// this feature, or the unit tests of this module for an example.
221	    ///
222	    /// # Failure
223	    ///
224	    /// Will panic if `arg` is greater than or equal to
225	    /// [`self.len()`](Context::len).
226	    pub fn set_aux<T: Send + Sync + 'static>(&self, arg: c_int, value: T) -> Result<Arc<T>> {
227	        assert!(arg < self.len() as i32);
228	        let orig: Arc<T> = Arc::new(value);
229	        let inner: AuxInner = orig.clone();
230	        let outer = Box::new(inner);
231	        let raw: *mut AuxInner = Box::into_raw(outer);
232	        unsafe {
233	            ffi::sqlite3_set_auxdata(
234	                self.ctx,
235	                arg,
236	                raw.cast(),
237	                Some(free_boxed_value::<AuxInner>),
238	            );
239	        };
240	        Ok(orig)
241	    }
242	
243	    /// Gets the auxiliary data that was associated with a given parameter via
244	    /// [`set_aux`](Context::set_aux). Returns `Ok(None)` if no data has been
245	    /// associated, and Ok(Some(v)) if it has. Returns an error if the
246	    /// requested type does not match.
247	    ///
248	    /// # Failure
249	    ///
250	    /// Will panic if `arg` is greater than or equal to
251	    /// [`self.len()`](Context::len).
252	    pub fn get_aux<T: Send + Sync + 'static>(&self, arg: c_int) -> Result<Option<Arc<T>>> {
253	        assert!(arg < self.len() as i32);
254	        let p = unsafe { ffi::sqlite3_get_auxdata(self.ctx, arg) as *const AuxInner };
255	        if p.is_null() {
256	            Ok(None)
257	        } else {
258	            let v: AuxInner = AuxInner::clone(unsafe { &*p });
259	            v.downcast::<T>()
260	                .map(Some)
261	                .map_err(|_| Error::GetAuxWrongType)
262	        }
263	    }
264	
265	    /// Get the db connection handle via [sqlite3_context_db_handle](https://www.sqlite.org/c3ref/context_db_handle.html)
266	    ///
267	    /// # Safety
268	    ///
269	    /// This function is marked unsafe because there is a potential for other
270	    /// references to the connection to be sent across threads, [see this comment](https://github.com/rusqlite/rusqlite/issues/643#issuecomment-640181213).
271	    pub unsafe fn get_connection(&self) -> Result<ConnectionRef<'_>> {
272	        unsafe {
273	            let handle = ffi::sqlite3_context_db_handle(self.ctx);
274	            Ok(ConnectionRef {
275	                conn: Connection::from_handle(handle)?,
276	                phantom: PhantomData,
277	            })
278	        }
279	    }
280	}
