299	type AuxInner = Arc<dyn Any + Send + Sync + 'static>;
300	
301	/// Subtype of an SQL function
302	pub type SubType = Option<c_uint>;
303	
304	/// Result of an SQL function
305	pub trait SqlFnOutput {
306	    /// Converts Rust value to SQLite value with an optional subtype
307	    fn to_sql(&self) -> Result<(ToSqlOutput<'_>, SubType)>;
308	}
309	
310	impl<T: ToSql> SqlFnOutput for T {
311	    #[inline]
312	    fn to_sql(&self) -> Result<(ToSqlOutput<'_>, SubType)> {
313	        ToSql::to_sql(self).map(|o| (o, None))
314	    }
315	}
316	
317	impl<T: ToSql> SqlFnOutput for (T, SubType) {
318	    fn to_sql(&self) -> Result<(ToSqlOutput<'_>, SubType)> {
319	        ToSql::to_sql(&self.0).map(|o| (o, self.1))
320	    }
321	}
