323	/// n-th arg of an SQL scalar function
324	pub struct SqlFnArg {
325	    idx: usize,
326	}
327	impl ToSql for SqlFnArg {
328	    fn to_sql(&self) -> Result<ToSqlOutput<'_>> {
329	        Ok(ToSqlOutput::Arg(self.idx))
330	    }
331	}
