333	unsafe fn sql_result<T: SqlFnOutput>(
334	    ctx: *mut sqlite3_context,
335	    args: &[*mut sqlite3_value],
336	    r: Result<T>,
337	) {
338	    unsafe {
339	        if let Err(err) = _sql_result(ctx, args, r) {
340	            report_error(ctx, &err);
341	        }
342	    }
343	}
344	
345	unsafe fn _sql_result<T: SqlFnOutput>(
346	    ctx: *mut sqlite3_context,
347	    args: &[*mut sqlite3_value],
348	    r: Result<T>,
349	) -> Result<()> {
350	    let r = r?;
351	    let (value, sub_type) = r.to_sql()?;
352	    unsafe {
353	        set_result(ctx, args, value)?;
354	        if let Some(sub_type) = sub_type {
355	            ffi::sqlite3_result_subtype(ctx, sub_type);
356	        }
357	    }
358	    Ok(())
359	}
