409	bitflags::bitflags! {
410	    /// Function Flags.
411	    /// See [sqlite3_create_function](https://sqlite.org/c3ref/create_function.html)
412	    /// and [Function Flags](https://sqlite.org/c3ref/c_deterministic.html) for details.
413	    #[derive(Clone, Copy, Debug)]
414	    #[repr(C)]
415	    pub struct FunctionFlags: c_int {
416	        /// Specifies UTF-8 as the text encoding this SQL function prefers for its parameters.
417	        const SQLITE_UTF8     = ffi::SQLITE_UTF8;
418	        /// Specifies UTF-16 using little-endian byte order as the text encoding this SQL function prefers for its parameters.
419	        const SQLITE_UTF16LE  = ffi::SQLITE_UTF16LE;
420	        /// Specifies UTF-16 using big-endian byte order as the text encoding this SQL function prefers for its parameters.
421	        const SQLITE_UTF16BE  = ffi::SQLITE_UTF16BE;
422	        /// Specifies UTF-16 using native byte order as the text encoding this SQL function prefers for its parameters.
423	        const SQLITE_UTF16    = ffi::SQLITE_UTF16;
424	        /// Means that the function always gives the same output when the input parameters are the same.
425	        const SQLITE_DETERMINISTIC = ffi::SQLITE_DETERMINISTIC; // 3.8.3
426	        /// Means that the function may only be invoked from top-level SQL.
427	        const SQLITE_DIRECTONLY    = 0x0000_0008_0000; // 3.30.0
428	        /// Indicates to SQLite that a function may call `sqlite3_value_subtype()` to inspect the subtypes of its arguments.
429	        const SQLITE_SUBTYPE       = 0x0000_0010_0000; // 3.30.0
430	        /// Means that the function is unlikely to cause problems even if misused.
431	        const SQLITE_INNOCUOUS     = 0x0000_0020_0000; // 3.31.0
432	        /// Indicates to SQLite that a function might call `sqlite3_result_subtype()` to cause a subtype to be associated with its result.
433	        const SQLITE_RESULT_SUBTYPE     = 0x0000_0100_0000; // 3.45.0
434	        /// Indicates that the function is an aggregate that internally orders the values provided to the first argument.
435	        const SQLITE_SELFORDER1 = 0x0000_0200_0000; // 3.47.0
436	    }
437	}
