446	impl Connection {
447	    /// Attach a user-defined scalar function to
448	    /// this database connection.
449	    ///
450	    /// `fn_name` is the name the function will be accessible from SQL.
451	    /// `n_arg` is the number of arguments to the function. Use `-1` for a
452	    /// variable number. If the function always returns the same value
453	    /// given the same input, `deterministic` should be `true`.
454	    ///
455	    /// The function will remain available until the connection is closed or
456	    /// until it is explicitly removed via
457	    /// [`remove_function`](Connection::remove_function).
458	    ///
459	    /// # Example
460	    ///
461	    /// ```rust
462	    /// # use rusqlite::{Connection, Result};
463	    /// # use rusqlite::functions::FunctionFlags;
464	    /// fn scalar_function_example(db: Connection) -> Result<()> {
465	    ///     db.create_scalar_function(
466	    ///         "halve",
467	    ///         1,
468	    ///         FunctionFlags::SQLITE_UTF8 | FunctionFlags::SQLITE_DETERMINISTIC,
469	    ///         |ctx| {
470	    ///             let value = ctx.get::<f64>(0)?;
471	    ///             Ok(value / 2f64)
472	    ///         },
473	    ///     )?;
474	    ///
475	    ///     let six_halved: f64 = db.query_row("SELECT halve(6)", [], |r| r.get(0))?;
476	    ///     assert_eq!(six_halved, 3f64);
477	    ///     Ok(())
478	    /// }
479	    /// ```
480	    ///
481	    /// # Failure
482	    ///
483	    /// Will return Err if the function could not be attached to the connection.
484	    #[inline]
485	    pub fn create_scalar_function<F, N: Name, T>(
486	        &self,
487	        fn_name: N,
488	        n_arg: c_int,
489	        flags: FunctionFlags,
490	        x_func: F,
491	    ) -> Result<()>
492	    where
493	        F: Fn(&Context<'_>) -> Result<T> + Send + 'static,
494	        T: SqlFnOutput,
495	    {
496	        self.db
497	            .borrow_mut()
498	            .create_scalar_function(fn_name, n_arg, flags, x_func)
499	    }
500	
501	    /// Attach a user-defined aggregate function to this
502	    /// database connection.
503	    ///
504	    /// # Failure
505	    ///
506	    /// Will return Err if the function could not be attached to the connection.
507	    #[inline]
508	    pub fn create_aggregate_function<A, D, N: Name, T>(
509	        &self,
510	        fn_name: N,
511	        n_arg: c_int,
512	        flags: FunctionFlags,
513	        aggr: D,
514	    ) -> Result<()>
515	    where
516	        A: RefUnwindSafe + UnwindSafe + Send,
517	        D: Aggregate<A, T> + Send + 'static,
518	        T: SqlFnOutput,
519	    {
520	        self.db
521	            .borrow_mut()
522	            .create_aggregate_function(fn_name, n_arg, flags, aggr)
523	    }
524	
525	    /// Attach a user-defined aggregate window function to
526	    /// this database connection.
527	    ///
528	    /// See `https://sqlite.org/windowfunctions.html#udfwinfunc` for more
529	    /// information.
530	    #[cfg(feature = "window")]
531	    #[inline]
532	    pub fn create_window_function<A, N: Name, W, T>(
533	        &self,
534	        fn_name: N,
535	        n_arg: c_int,
536	        flags: FunctionFlags,
537	        aggr: W,
538	    ) -> Result<()>
539	    where
540	        A: RefUnwindSafe + UnwindSafe + Send,
541	        W: WindowAggregate<A, T> + Send + 'static,
542	        T: SqlFnOutput,
543	    {
544	        self.db
545	            .borrow_mut()
546	            .create_window_function(fn_name, n_arg, flags, aggr)
547	    }
548	
549	    /// Removes a user-defined function from this
550	    /// database connection.
551	    ///
552	    /// `fn_name` and `n_arg` should match the name and number of arguments
553	    /// given to [`create_scalar_function`](Connection::create_scalar_function)
554	    /// or [`create_aggregate_function`](Connection::create_aggregate_function).
555	    ///
556	    /// # Failure
557	    ///
558	    /// Will return Err if the function could not be removed.
559	    #[inline]
560	    pub fn remove_function<N: Name>(&self, fn_name: N, n_arg: c_int) -> Result<()> {
561	        self.db.borrow_mut().remove_function(fn_name, n_arg)
562	    }
563	}
