729	unsafe extern "C" fn call_boxed_step<A, D, T>(
730	    ctx: *mut sqlite3_context,
731	    argc: c_int,
732	    argv: *mut *mut sqlite3_value,
733	) where
734	    A: RefUnwindSafe + UnwindSafe,
735	    D: Aggregate<A, T>,
736	    T: SqlFnOutput,
737	{
738	    unsafe {
739	        let Some(pac) = aggregate_context::<A>(ctx, size_of::<*mut A>()) else {
740	            ffi::sqlite3_result_error_nomem(ctx);
741	            return;
742	        };
743	
744	        let r = catch_unwind(|| {
745	            let boxed_aggr: *mut D = ffi::sqlite3_user_data(ctx).cast::<D>();
746	            assert!(
747	                !boxed_aggr.is_null(),
748	                "Internal error - null aggregate pointer"
749	            );
750	            let mut ctx = Context {
751	                ctx,
752	                args: slice::from_raw_parts(argv, argc as usize),
753	            };
754	
755	            if (*pac).is_null() {
756	                *pac = Box::into_raw(Box::new((*boxed_aggr).init(&mut ctx)?));
757	            }
758	
759	            (*boxed_aggr).step(&mut ctx, &mut **pac)
760	        });
761	        let Ok(r) = r else {
762	            report_error(ctx, &Error::UnwindingPanic);
763	            return;
764	        };
765	        match r {
766	            Ok(()) => {}
767	            Err(err) => report_error(ctx, &err),
768	        }
769	    }
770	}
