811	unsafe extern "C" fn call_boxed_final<A, D, T>(ctx: *mut sqlite3_context)
812	where
813	    A: RefUnwindSafe + UnwindSafe,
814	    D: Aggregate<A, T>,
815	    T: SqlFnOutput,
816	{
817	    unsafe {
818	        // Within the xFinal callback, it is customary to set N=0 in calls to
819	        // sqlite3_aggregate_context(C,N) so that no pointless memory allocations occur.
820	        let a: Option<A> = match aggregate_context::<A>(ctx, 0) {
821	            Some(pac) => {
822	                if (*pac).is_null() {
823	                    None
824	                } else {
825	                    let a = Box::from_raw(*pac);
826	                    Some(*a)
827	                }
828	            }
829	            None => None,
830	        };
831	
832	        let r = catch_unwind(|| {
833	            let boxed_aggr: *mut D = ffi::sqlite3_user_data(ctx).cast::<D>();
834	            assert!(
835	                !boxed_aggr.is_null(),
836	                "Internal error - null aggregate pointer"
837	            );
838	            let mut ctx = Context { ctx, args: &mut [] };
839	            (*boxed_aggr).finalize(&mut ctx, a)
840	        });
841	        let Ok(r) = r else {
842	            report_error(ctx, &Error::UnwindingPanic);
843	            return;
844	        };
845	        sql_result(ctx, &[], r);
846	    }
847	}
