40	    pub fn open_with_flags(
41	        c_path: &CStr,
42	        mut flags: OpenFlags,
43	        vfs: Option<&CStr>,
44	    ) -> Result<Self> {
45	        ensure_safe_sqlite_threading_mode()?;
46	
47	        let z_vfs = match vfs {
48	            Some(c_vfs) => c_vfs.as_ptr(),
49	            None => ptr::null(),
50	        };
51	
52	        // turn on extended results code before opening database to have a better diagnostic if a failure happens
53	        let exrescode = if version_number() >= 3_037_000 {
54	            flags |= OpenFlags::SQLITE_OPEN_EXRESCODE;
55	            true
56	        } else {
57	            false // flag SQLITE_OPEN_EXRESCODE is ignored by SQLite version < 3.37.0
58	        };
59	
60	        unsafe {
61	            let mut db: *mut ffi::sqlite3 = ptr::null_mut();
62	            let r = ffi::sqlite3_open_v2(c_path.as_ptr(), &raw mut db, flags.bits(), z_vfs);
63	            if r != ffi::SQLITE_OK {
64	                let e = if db.is_null() {
65	                    err!(r, "{}", c_path.to_string_lossy())
66	                } else {
67	                    let mut e = error_from_handle(db, r);
68	                    if let Error::SqliteFailure(
69	                        ffi::Error {
70	                            code: ffi::ErrorCode::CannotOpen,
71	                            ..
72	                        },
73	                        Some(msg),
74	                    ) = e
75	                    {
76	                        e = err!(r, "{msg}: {}", c_path.to_string_lossy());
77	                    }
78	                    ffi::sqlite3_close(db);
79	                    e
80	                };
81	
82	                return Err(e);
83	            }
84	
85	            // attempt to turn on extended results code; don't fail if we can't.
86	            if !exrescode {
87	                ffi::sqlite3_extended_result_codes(db, 1);
88	            }
89	
90	            let r = ffi::sqlite3_busy_timeout(db, 5000);
91	            if r != ffi::SQLITE_OK {
92	                let e = error_from_handle(db, r);
93	                ffi::sqlite3_close(db);
94	                return Err(e);
95	            }
96	
97	            Ok(Self::new(db, true))
98	        }
99	    }
