/// The original error reported by the most recent failing call to a scalar
/// function registered with
/// [`create_scalar_function_with_error`](Connection::create_scalar_function_with_error)
/// on a connection, along with the SQLite result code it was reported as.
///
/// SQLite only carries the result code and message back to the caller; the
/// original error is kept here so that the rusqlite call that triggered the
/// failure can report it instead of the generic SQLite error. The slot is
/// cleared at the start of every such function call and the error is taken
/// when the failing call is decoded, so a stale error can never be
/// attributed to a later, unrelated failure.
#[derive(Default)]
struct ScalarFunctionError {
    error: Option<(c_int, Error)>,
}

unsafe fn scalar_function_error_slot(db: *mut ffi::sqlite3) -> *mut ScalarFunctionError {
    unsafe { ffi::sqlite3_get_clientdata(db, c"sqlite3_create_function".as_ptr()) }
        .cast::<ScalarFunctionError>()
}

/// The SQLite result code [`report_error`] reports `err` as.
fn scalar_function_error_code(err: &Error) -> c_int {
    match *err {
        Error::SqliteFailure(ref err, _) => err.extended_code,
        _ => ffi::SQLITE_CONSTRAINT_FUNCTION,
    }
}

/// If `code` is the SQLite result code that the most recent failing
/// error-preserving scalar function call on `db` was reported as, take and
/// return the original error. The error is consumed, so it is reported at
/// most once, by the call that triggered the failure.
pub(crate) unsafe fn take_scalar_function_error(
    db: *mut ffi::sqlite3,
    code: c_int,
) -> Option<Error> {
    if db.is_null() {
        return None;
    }
    let state = unsafe { scalar_function_error_slot(db) };
    if state.is_null() {
        return None;
    }
    match unsafe { &(*state).error } {
        Some((c, _)) if *c == code => unsafe { (*state).error.take().map(|(_, err)| err) },
        _ => None,
    }
}
```

