pub unsafe fn error_from_handle(db: *mut ffi::sqlite3, code: c_int) -> Error {
    // A scalar function registered with `create_scalar_function_with_error`
    // keeps its original error on the connection; the call that triggered
    // the failure reports that error instead of the generic SQLite one.
    #[cfg(feature = "functions")]
    if let Some(err) = unsafe { crate::functions::take_scalar_function_error(db, code) } {
        return err;
    }
    // A commit rejected by a `try_commit_hook` carries its own reason.
    #[cfg(feature = "hooks")]
    if let Some(err) = unsafe { crate::hooks::take_try_commit_hook_error(db, code) } {
        return err;
    }
    // A failed `wal_hook` notification surfaces as a generic `SQLITE_ERROR`;
    // the hook's own error is the real reason.
    #[cfg(feature = "hooks")]
    if let Some(err) = unsafe { crate::hooks::take_wal_hook_error(db, code) } {
        return err;
    }
    // An access rejected by a `try_authorizer` surfaces as a generic
    // `SQLITE_ERROR` ("authorizer malfunction"); the authorizer's own error
    // is the real reason.
    #[cfg(feature = "hooks")]
    if let Some(err) = unsafe { crate::hooks::take_authorizer_error(db, code) } {
        return err;
    }
    error_from_sqlite_code(code, unsafe { error_msg(db, code) })
}

unsafe fn error_msg(db: *mut ffi::sqlite3, code: c_int) -> Option<String> {
    unsafe {
        if db.is_null() || ffi::sqlite3_errcode(db) != code {
            let err_str = ffi::sqlite3_errstr(code);
            if err_str.is_null() {
                None
            } else {
                Some(errmsg_to_string(err_str))
            }
        } else {
            Some(errmsg_to_string(ffi::sqlite3_errmsg(db)))
        }
    }
}

pub unsafe fn decode_result_raw(db: *mut ffi::sqlite3, code: c_int) -> Result<()> {
    if code == ffi::SQLITE_OK {
        Ok(())
