        c"panics",
        1,
        FunctionFlags::SQLITE_UTF8,
        |ctx| -> Result<i64> {
            let x = ctx.get::<i64>(0)?;
            assert!(x >= 0, "boom");
            Ok(x)
        },
    )?;
    assert_eq!(
        Error::UnwindingPanic,
        db.one_column::<i64, _>("SELECT panics(-1)", []).unwrap_err()
