        // each execution of the cached statement reports its own error
        assert_custom_error(stmt.query_one([-i], |r| r.get::<_, i64>(0)).unwrap_err(), -i);
        assert_eq!(i, stmt.query_one([i], |r| r.get::<_, i64>(0))?);
    }
